import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Migration status","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/MIGRATION_STATUS.html"}],["meta",{"property":"og:title","content":"Migration status | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/MIGRATION_STATUS.html"}],["meta",{"name":"twitter:title","content":"Migration status | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"MIGRATION_STATUS.md","filePath":"MIGRATION_STATUS.md","lastUpdated":1793948202000}`),a={name:`MIGRATION_STATUS.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="migration-status" tabindex="-1">Migration status <a class="header-anchor" href="#migration-status" aria-label="Permalink to “Migration status”">​</a></h1><h2 id="implemented" tabindex="-1">Implemented <a class="header-anchor" href="#implemented" aria-label="Permalink to “Implemented”">​</a></h2><ul><li>Runtime-neutral date, interest, account, FD product, event, booking and result primitives.</li><li>Configuration validation and recurring/scheduled inflow/outflow expansion.</li><li>Event-driven Greedy simulation with multiple accounts, transfers, account-level eFD eligibility, booking/maturity/payout events, AIT, fees, outflows and final sweep.</li><li><strong>Absolute R strategy port:</strong> exhaustive branch-and-bound search, Greedy incumbent, admissible optimistic bound, transposition pruning, local booking combinations, consolidation and carry-forward decisions, and replay into the canonical event ledger.</li><li><strong>Absolute R+ strategy port:</strong> layered beam search, root-strategy diversity, bounded local booking combinations, optional state cap, inflow-aware waiting priority, payout-aware dominance pruning, diagnostics and canonical replay.</li><li>Absolute R+ configuration through <code>gaml_settings</code> (<code>beam_width</code>, <code>max_local_branches</code>, <code>max_decisions</code>), with CLI overrides.</li><li>Shared strategy entry points in <code>src/strategies/</code>; each strategy has its own module and uses the same Node/browser-compatible financial search and replay core.</li><li>Node CSV parser and file adapters for the bank registry and bank-specific FD product catalogue.</li><li>Root data catalogue populated from archived bank and FD CSV datasets.</li><li>Node CLI supports Greedy, Absolute R and Absolute R+, prints search diagnostics for optimizer strategies, and writes a standalone HTML report.</li><li>Unit tests for search primitives, search drivers, strategy execution, future-inflow decisions, Absolute R+ settings, CLI integration and account-level eFD eligibility.</li></ul><h2 id="not-yet-equivalent-to-the-python-application" tabindex="-1">Not yet equivalent to the Python application <a class="header-anchor" href="#not-yet-equivalent-to-the-python-application" aria-label="Permalink to “Not yet equivalent to the Python application”">​</a></h2><ul><li>Full Python-vs-JavaScript golden fixture parity across the archived scenarios, payout types, AIT, transfer fees, multi-account cases and strict/deferred/best-effort outflows.</li><li>Performance benchmarking of Absolute R on the largest archived scenarios and Absolute R+ default settings against the Python baseline.</li><li>Full legacy console formatter parity, XIRR and complete decision-log generation.</li><li>Python report-template port is implemented in JavaScript, including the eight-section dark layout, embedded styling and chart interactions; detailed content parity and visual regression against Python-generated reports still require validation.</li><li>Browser application, browser strategy configuration UI, browser parity tests and GitHub Pages deployment.</li><li>Python CLI parity for strategy comparison, plotting and all ancillary CLI options.</li></ul><p>The strategy ports are implemented and the automated Node test suite is passing on the migration branch, but they are not yet financially certified against Python golden outputs. Do not merge to <code>main</code> or deploy until that parity and performance validation is complete.</p>`,6)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};